1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { registrarConfigured, transfersAvailable, getDnsHosts } from "@/lib/registrar";
5	import { StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
6	import { PortalHero } from "@/components/portal/PortalHero";
7	import { DomainSearch } from "@/components/customer/DomainSearch";
8	import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
9	import { findDomainInboxPlan } from "@/lib/domain-inbox-email";
10	
11	export const dynamic = "force-dynamic";
12	
13	function daysUntil(d: Date): number {
14	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
15	}
16	
17	function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
18	  if (days === null) return "slate";
19	  if (days < 0) return "red";
20	  if (days <= 30) return "amber";
21	  return "green";
22	}
23	
24	function expiryLabel(d: Date | null): string {
25	  if (!d) return "—";
26	  const days = daysUntil(d);
27	  if (days < 0) return `expired ${-days}d ago`;
28	  if (days === 0) return "expires today";
29	  return `in ${days} day${days === 1 ? "" : "s"}`;
30	}
31	
32	const statusDotFor = (s: string) =>
33	  s === "ACTIVE"
34	    ? "RUNNING"
35	    : s === "PENDING" || s === "TRANSFER_PENDING"
36	      ? "PENDING"
37	      : s === "EXPIRED"
38	        ? "SUSPENDED"
39	        : "ERROR";
40	
41	/** Email Inbox cell — real per-domain state, never a marketing placeholder.
42	 *  `sub` is this domain's EmailSubscription (created automatically for every
43	 *  NEW registration since the free-inbox feature shipped — see
44	 *  lib/domain-inbox-email.ts). Domains registered before that, or where the
45	 *  customer skipped naming a mailbox, show a real "Set up" CTA instead. */
46	function EmailInboxCell({
47	  sub,
48	  compact,
49	}: {
50	  sub: { activeMailboxes: number; totalMailboxes: number } | null;
51	  compact?: boolean;
52	}) {
53	  if (!sub) {
54	    return (
55	      <Link
56	        href="/dashboard/email"
57	        className={compact ? "text-xs font-medium text-brand-300 hover:text-brand-200" : "btn-secondary px-3 py-1 text-xs"}
58	      >
59	        Set up →
60	      </Link>
61	    );
62	  }
63	  if (sub.totalMailboxes === 0) {
64	    return (
65	      <span className="flex items-center gap-2">
66	        <Badge tone="amber">No mailbox yet</Badge>
67	        <Link href="/dashboard/email" className="text-xs font-medium text-brand-300 hover:text-brand-200">
68	          Set up →
69	        </Link>
70	      </span>
71	    );
72	  }
73	  return (
74	    <Badge tone={sub.activeMailboxes > 0 ? "green" : "slate"}>
75	      {sub.activeMailboxes > 0
76	        ? `Active · ${sub.activeMailboxes} mailbox${sub.activeMailboxes === 1 ? "" : "es"}`
77	        : "Provisioning"}
78	    </Badge>
79	  );
80	}
81	
82	function nameserversLabel(ns: string[]): string {
83	  if (ns.length === 0) return "Default nameservers";
84	  const shown = ns.slice(0, 2).join(", ");
85	  return ns.length > 2 ? `${shown} +${ns.length - 2}` : shown;
86	}
87	
88	export default async function DomainsPage() {
89	  const user = await requireUser();
90	  const configured = registrarConfigured();
91	  const canTransfer = transfersAvailable();
92	  const domains = await db.domain.findMany({
93	    where: { userId: user.id },
94	    orderBy: { createdAt: "desc" },
95	  });
96	
97	  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
98	  const recordCounts = new Map<string, number | null>();
99	  if (configured) {
100	    await Promise.all(
101	      domains
102	        .filter((d) => d.status === "ACTIVE")
103	        .map(async (d) => {
104	          try {
105	            const hosts = await getDnsHosts(d.name);
106	            recordCounts.set(d.id, hosts.length);
107	          } catch {
108	            recordCounts.set(d.id, null);
109	          }
110	        })
111	    );
112	  }
113	
114	  // Real per-domain free-inbox state (Part 2). Only domains registered since
115	  // the feature shipped have a row here — nothing is backfilled onto older
116	  // domains, so a "Set up" CTA for those is accurate, not a bug.
117	  const emailSubs = domains.length
118	    ? await db.emailSubscription.findMany({
119	        where: { userId: user.id, domainName: { in: domains.map((d) => d.name) }, status: { not: "CANCELLED" } },
120	        select: { domainName: true, mailboxes: { select: { status: true } } },
121	      })
122	    : [];
123	  const subByDomain = new Map(
124	    emailSubs.map((s) => [
125	      s.domainName,
126	      {
127	        totalMailboxes: s.mailboxes.length,
128	        activeMailboxes: s.mailboxes.filter((m) => m.status === "ACTIVE").length,
129	      },
130	    ])
131	  );
132	
133	  // Real numbers for the cross-sell banner — never a guessed figure.
134	  const inboxPlan = await findDomainInboxPlan();
135	
136	  const active = domains.filter((d) => d.status === "ACTIVE").length;
137	  const expiringSoon = domains.filter(
138	    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
139	  ).length;
140	  const expiringToday = domains.filter(
141	    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) === 0
142	  ).length;
143	  const autoRenewOn = domains.filter((d) => d.autoRenew).length;
144	
145	  // Quick Actions in the sidebar need a concrete domain to manage — the most
146	  // recently registered one (list is already ordered createdAt desc).
147	  const primaryDomain = domains.find((d) => d.status === "ACTIVE") ?? domains[0] ?? null;
148	
149	  return (
150	    <div className="space-y-6">
151	      <PortalHero variant="domains" title="Domains" sub="Register, transfer in and manage domains, right next to your servers.">
152	        {canTransfer && (
153	          <Link href="/dashboard/domains/transfer" className="btn-secondary">
154	            Transfer a domain in
155	          </Link>
156	        )}
157	        {configured && (
158	          <Link href="/dashboard/domains/ideas" className="btn-secondary">
159	            Find a name
160	          </Link>
161	        )}
162	        {configured && (
163	          <Link href="/dashboard/domains/register" className="btn-primary">
164	            Register a domain
165	          </Link>
166	        )}
167	      </PortalHero>
168	
169	      {domains.length > 0 && (
170	        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
171	          <StatCard
172	            label="Total domains"
173	            value={String(domains.length)}
174	            icon={
175	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
176	                <circle cx="12" cy="12" r="9" />
177	                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
178	              </svg>
179	            }
180	          />
181	          <StatCard
182	            label="Expiring soon"
183	            value={String(expiringSoon)}
184	            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
185	            deltaGood={expiringSoon === 0}
186	            icon={
187	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
188	                <circle cx="12" cy="12" r="9" />
189	                <path d="M12 7v5l3.5 2" />
190	              </svg>
191	            }
192	          />
193	          <StatCard
194	            label="Expiring today"
195	            value={String(expiringToday)}
196	            delta={expiringToday === 0 ? "nothing today" : "renew now"}
197	            deltaGood={expiringToday === 0}
198	            icon={
199	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
200	                <path d="M12 9v4M12 16.5h.01" />
201	                <path d="M10.3 3.9 2.7 17.1a1.6 1.6 0 0 0 1.4 2.4h15.8a1.6 1.6 0 0 0 1.4-2.4L13.7 3.9a1.6 1.6 0 0 0-2.8 0Z" />
202	              </svg>
203	            }
204	          />
205	          <StatCard
206	            label="Auto renew on"
207	            value={String(autoRenewOn)}
208	            delta={autoRenewOn === domains.length ? "all covered" : `${domains.length - autoRenewOn} off`}
209	            deltaGood={autoRenewOn === domains.length}
210	            icon={
211	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
212	                <path d="M3 12a9 9 0 0 1 15.4-6.4L21 8M21 3v5h-5" />
213	                <path d="M21 12a9 9 0 0 1-15.4 6.4L3 16M3 21v-5h5" />
214	              </svg>
215	            }
216	          />
217	        </div>
218	      )}
219	
220	      {/* Cross-sell banner — the claim is real: every domain registered from
221	          here on gets a genuine EmailSubscription + reserved mailbox slot,
222	          not just a marketing line (see lib/domain-inbox-email.ts). */}
223	      <div className="card relative overflow-hidden border-emerald-500/20 bg-gradient-to-br from-emerald-500/[0.07] to-transparent p-5 sm:p-6">
224	        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
225	          <div className="flex items-start gap-4">
226	            <span className="flex h-11 w-11 flex-none items-center justify-center rounded-xl border border-emerald-500/20 bg-emerald-500/10 text-emerald-300">
227	              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
228	                <rect x="3" y="5" width="18" height="14" rx="2" />
229	                <path d="m3.5 7 8.5 6 8.5-6" />
230	              </svg>
231	            </span>
232	            <div>
233	              <h2 className="font-semibold text-white">Every new domain comes with a free Business Email inbox</h2>
234	              <p className="mt-1 max-w-xl text-sm text-slate-400">
235	                Register a domain and set up you@yourdomain in the same flow —{" "}
236	                {inboxPlan ? `${inboxPlan.mailboxes} mailbox, ${inboxPlan.storageGB} GB, ` : ""}
237	                free for as long as the domain is active. Already have a domain here? Add its inbox any
238	                time from Email.
239	              </p>
240	            </div>
241	          </div>
242	          <Link href="/dashboard/email" className="btn-secondary shrink-0 self-start sm:self-center">
243	            Learn more →
244	          </Link>
245	        </div>
246	      </div>
247	
248	      <div className="grid gap-6 lg:grid-cols-[1fr_340px]">
249	        <div className="space-y-6">
250	          <DomainSearch configured={configured} />
251	
252	          {domains.length === 0 ? (
253	            <EmptyState
254	              title="No domains yet"
255	              sub={
256	                configured
257	                  ? "Search above for an exact name, or let the generator turn a description of your business into available ones — then register and point it at any of your servers in minutes."
258	                  : "Domain registration lights up once this feature is configured. Your registered domains will appear here."
259	              }
260	              action={
261	                configured || canTransfer ? (
262	                  <div className="flex flex-wrap items-center justify-center gap-3">
263	                    {configured && (
264	                      <Link href="/dashboard/domains/register" className="btn-primary">
265	                        Register your first domain
266	                      </Link>
267	                    )}
268	                    {configured && (
269	                      <Link href="/dashboard/domains/ideas" className="btn-secondary">
270	                        Not sure what to call it? Generate names
271	                      </Link>
272	                    )}
273	                    {canTransfer && (
274	                      <Link href="/dashboard/domains/transfer" className="btn-secondary">
275	                        Already own one? Transfer it in
276	                      </Link>
277	                    )}
278	                  </div>
279	                ) : undefined
280	              }
281	            />
282	          ) : (
283	            <div className="card p-0">
284	              <div className="flex items-center justify-between px-5 pt-5">
285	                <p className="section-label">Your domains</p>
286	                <span className="text-xs text-slate-500">{domains.length} total</span>
287	              </div>
288	
289	              {/* Card grid on small screens, table on large */}
290	              <div className="grid gap-3 p-5 lg:hidden">
291	                {domains.map((d) => {
292	                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
293	                  const count = recordCounts.get(d.id);
294	                  const sub = subByDomain.get(d.name) ?? null;
295	                  return (
296	                    <Link
297	                      key={d.id}
298	                      href={`/dashboard/domains/${d.id}`}
299	                      className="card card-hover block p-4"
300	                    >
301	                      <div className="flex items-center justify-between gap-2">
302	                        {/* min-w-0 so `truncate` can actually shrink a long domain
303	                            name at 390px instead of pushing the status dot off-card. */}
304	                        <span className="min-w-0 truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
305	                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
306	                      </div>
307	                      {d.status === "TRANSFER_PENDING" && (
308	                        <p className="mt-2 text-xs text-amber-300">
309	                          Transfer in progress — approve the confirmation email from your old registrar. Usually
310	                          5–7 days.
311	                        </p>
312	                      )}
313	                      {d.status === "TRANSFER_FAILED" && (
314	                        <p className="mt-2 text-xs text-red-300">
315	                          Transfer didn&apos;t complete — you were credited back. Tap to see why.
316	                        </p>
317	                      )}
318	                      <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
319	                        {d.status === "TRANSFER_PENDING" ? (
320	                          <Badge tone="amber">transfer in</Badge>
321	                        ) : (
322	                          <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
323	                        )}
324	                        <Badge tone={d.autoRenew ? "green" : "slate"}>
325	                          auto-renew {d.autoRenew ? "on" : "off"}
326	                        </Badge>
327	                        {d.status === "ACTIVE" && (
328	                          <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
329	                        )}
330	                        <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
331	                      </div>
332	                      <div className="mt-2 flex items-center justify-between gap-2 border-t border-white/[0.05] pt-2 text-xs">
333	                        <span className="text-slate-500">Email inbox</span>
334	                        <EmailInboxCell sub={sub} compact />
335	                      </div>
336	                      <div className="mt-1 flex items-center justify-between gap-2 text-xs">
337	                        <span className="text-slate-500">Nameservers</span>
338	                        <span className="truncate font-mono text-slate-400">{nameserversLabel(d.nameservers)}</span>
339	                      </div>
340	                    </Link>
341	                  );
342	                })}
343	              </div>
344	
345	              <div className="hidden overflow-x-auto lg:block">
346	                <table className="table-shell mt-2 min-w-[980px]">
347	                  <thead>
348	                    <tr>
349	                      <th>Domain</th>
350	                      <th>Status</th>
351	                      <th>Expires</th>
352	                      <th>DNS</th>
353	                      <th>Nameservers</th>
354	                      <th>Email Inbox</th>
355	                      <th>Price</th>
356	                      <th>Auto-renew</th>
357	                      <th className="text-right">Actions</th>
358	                    </tr>
359	                  </thead>
360	                  <tbody>
361	                    {domains.map((d) => {
362	                      const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
363	                      const count = recordCounts.get(d.id);
364	                      const sub = subByDomain.get(d.name) ?? null;
365	                      return (
366	                        <tr key={d.id}>
367	                          <td>
368	                            <Link
369	                              href={`/dashboard/domains/${d.id}`}
370	                              className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
371	                            >
372	                              {d.name}
373	                            </Link>
374	                          </td>
375	                          <td>
376	                            <StatusDot status={statusDotFor(d.status)} label={d.status} />
377	                          </td>
378	                          <td>
379	                            {d.status === "TRANSFER_PENDING" ? (
380	                              <div className="flex flex-col">
381	                                <span className="text-sm text-amber-300">transferring in</span>
382	                                <span className="text-xs text-slate-500">approve the registrar email · 5–7 days</span>
383	                              </div>
384	                            ) : d.expiresAt ? (
385	                              <div className="flex flex-col">
386	                                <span className="text-sm text-slate-300">
387	                                  {d.expiresAt.toISOString().slice(0, 10)}
388	                                </span>
389	                                <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
390	                                  {expiryLabel(d.expiresAt)}
391	                                </span>
392	                              </div>
393	                            ) : (
394	                              <span className="text-slate-500">—</span>
395	                            )}
396	                          </td>
397	                          <td className="text-slate-400">
398	                            {d.status !== "ACTIVE"
399	                              ? "—"
400	                              : count === null || count === undefined
401	                                ? "—"
402	                                : `${count} record${count === 1 ? "" : "s"}`}
403	                          </td>
404	                          <td className="max-w-[180px] truncate font-mono text-xs text-slate-400">
405	                            {nameserversLabel(d.nameservers)}
406	                          </td>
407	                          <td>
408	                            <EmailInboxCell sub={sub} />
409	                          </td>
410	                          <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
411	                          <td>
412	                            <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
413	                          </td>
414	                          <td className="text-right">
415	                            <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
416	                              Manage
417	                            </Link>
418	                          </td>
419	                        </tr>
420	                      );
421	                    })}
422	                  </tbody>
423	                </table>
424	              </div>
425	            </div>
426	          )}
427	        </div>
428	
429	        {/* Sidebar — persistent CTAs + shortcuts, same two-column shape
430	            DomainRegisterWizard already uses (grid-cols-[1fr_320px]) for its
431	            own order-summary aside. */}
432	        <aside className="space-y-4">
433	          {configured && (
434	            <div className="card">
435	              <p className="section-label mb-2">Register a new domain</p>
436	              <p className="mb-3 text-sm text-slate-400">
437	                Search a name, pick a term, and it&apos;s live in minutes — with a free inbox included.
438	              </p>
439	              <Link href="/dashboard/domains/register" className="btn-primary w-full justify-center">
440	                Register a domain
441	              </Link>
442	            </div>
443	          )}
444	
445	          {canTransfer && (
446	            <div className="card">
447	              <p className="section-label mb-2">Transfer a domain</p>
448	              <p className="mb-3 text-sm text-slate-400">
449	                Already own one elsewhere? Move it in and manage it alongside your servers.
450	              </p>
451	              <Link href="/dashboard/domains/transfer" className="btn-secondary w-full justify-center">
452	                Start a transfer
453	              </Link>
454	            </div>
455	          )}
456	
457	          {primaryDomain && (
458	            <div className="card">
459	              <p className="section-label mb-3">
460	                Quick actions <span className="normal-case text-slate-500">· {primaryDomain.name}</span>
461	              </p>
462	              <div className="space-y-1">
463	                <Link
464	                  href={`/dashboard/domains/${primaryDomain.id}`}
465	                  className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
466	                >
467	                  Manage DNS
468	                  <span className="text-slate-600">→</span>
469	                </Link>
470	                <Link
471	                  href={`/dashboard/domains/${primaryDomain.id}`}
472	                  className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
473	                >
474	                  Nameservers
475	                  <span className="text-slate-600">→</span>
476	                </Link>
477	                <Link
478	                  href={`/dashboard/domains/${primaryDomain.id}`}
479	                  className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
480	                >
481	                  Domain lock
482	                  <span className="text-slate-600">→</span>
483	                </Link>
484	              </div>
485	            </div>
486	          )}
487	
488	          <div className="card">
489	            <p className="section-label mb-3">Need help?</p>
490	            <div className="space-y-1">
491	              <Link
492	                href="/help"
493	                className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
494	              >
495	                Help center
496	                <span className="text-slate-600">→</span>
497	              </Link>
498	              <Link
499	                href="/tools"
500	                className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
501	              >
502	                Free DNS &amp; domain tools
503	                <span className="text-slate-600">→</span>
504	              </Link>
505	              <Link
506	                href="/contact"
507	                className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 hover:bg-white/[0.04]"
508	              >
509	                Contact support
510	                <span className="text-slate-600">→</span>
511	              </Link>
512	            </div>
513	          </div>
514	        </aside>
515	      </div>
516	    </div>
517	  );
518	}
