1	import { notFound } from "next/navigation";
2	import Link from "next/link";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import {
6	  getDnsHosts,
7	  registrarConfigured,
8	  registrarSafeMessage,
9	  transferStatusLabel,
10	  type DnsHost,
11	} from "@/lib/registrar";
12	import { transferChargeCents } from "@/lib/domain-transfer";
13	import { TransferInStatusCard } from "@/components/customer/DomainTransferIn";
14	import { getRegistrarLock, listRedirects } from "@/lib/actions-domains-dns";
15	import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
16	import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
17	import { AutoRefresh } from "@/components/AutoRefresh";
18	import {
19	  DomainAutoRenewToggle,
20	  RenewDomainButton,
21	  DnsAddForm,
22	  DnsDeleteButton,
23	} from "@/components/customer/DomainControls";
