36	function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
37	  if (!d) return { text: "—", tone: "slate" };
38	  const days = daysUntil(d);
39	  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
40	  if (days === 0) return { text: "expires today", tone: "red" };
41	  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
42	  return { text: `in ${days} days`, tone: "green" };
43	}
