65	      {result.skipped && result.skipped.length > 0 && (
66	        <p className="text-slate-500">Already present ({result.skipped.length}): {result.skipped.join(", ")}</p>
67	      )}
68	      {result.failed && result.failed.length > 0 && (
69	        <p className="text-amber-400">
70	          Failed: {result.failed.map((f) => `${f.record} (${f.reason})`).join("; ")}
71	        </p>
72	      )}
73	      {result.note && <p className="text-slate-500">{result.note}</p>}
74	      {result.added && result.added.length === 0 && (!result.failed || result.failed.length === 0) && (
75	        <p className="text-slate-500">Everything was already in place — nothing to add.</p>
