37	  if (!isStaffPortal) return href;
38	  for (const [adminPrefix, staffPrefix] of Object.entries(ADMIN_TO_STAFF_HREF)) {
39	    if (href === adminPrefix || href.startsWith(`${adminPrefix}/`)) {
40	      return staffPrefix + href.slice(adminPrefix.length);
41	    }
42	  }
43	  return href;
44	}
