271	  const pathname = usePathname();
272	  // Which portal is this Shell rendering? The admin ops layout passes tag="ops",
273	  // the new employee portal (app/staff/layout.tsx) passes tag="staff", and the
274	  // customer dashboard passes none. This drives which floating widgets mount:
275	  // the customer portal keeps the Feedback bubble (and the live-chat bubble from
276	  // the root layout), while both staff-facing portals swap them for the
277	  // support + email attention indicators. (Role is NOT a reliable signal here —
278	  // an ADMIN visiting /dashboard is still on the customer portal, and an ADMIN
279	  // previewing /staff is still on the employee portal.)
280	  const isAdminPortal = tag === "ops";
281	  const isStaffPortal = tag === "staff";
282	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
283	  // main so they fill the entire content area under the header with no gap.
284	  // /staff/inbox mirrors /admin/inbox (same underlying mail view, Phase 5).
285	  const fullBleed =
286	    pathname === "/dashboard/mail" ||
287	    pathname === "/dashboard/calendar" ||
288	    pathname === "/admin/inbox" ||
289	    pathname === "/admin/board" ||
290	    pathname === "/admin/reddit" ||
291	    pathname === "/staff/inbox" ||
292	    pathname === "/staff/reddit";
293	  // Wide (but still centered/padded, unlike fullBleed) routes — data-table-heavy
294	  // pages that were clipping real columns (Time on page/Account/Referrer) at
295	  // the standard 1280px cap. Keeps the page's own section padding/spacing
296	  // (fullBleed strips that entirely, which this page still relies on for its
297	  // stacked stat-card/globe/table sections) while giving the traffic feed
298	  // table room to actually show its columns instead of truncating them.
299	  const wideContent = pathname === "/admin/visitors";
300	  const [notifOpen, setNotifOpen] = useState(false);
301	  const [sidebarOpen, setSidebarOpen] = useState(false);
302	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
303	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
304	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
305	  const [collapsed, setCollapsed] = useState(false);
306	  const [, startTransition] = useTransition();
307	
308	  useEffect(() => {
309	    try {
310	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
311	    } catch {}
312	  }, []);
313	  function toggleCollapsed() {
314	    setCollapsed((c) => {
315	      const next = !c;
316	      try {
317	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
318	      } catch {}
319	      return next;
320	    });
321	  }
322	
323	  /**
324	   * Per-group collapse (admin portal only). Sits alongside the whole-rail
325	   * collapse above but tracks each nav SECTION independently, keyed by
326	   * `section.key` — a map of collapsed group keys to `true`, everything absent
327	   * defaults to expanded so a first-time admin (or the customer portal, which
328	   * never toggles this) sees exactly the same sidebar as before this existed.
329	   * Mirrors the rail-collapse persistence pattern: hydrate once on mount,
330	   * write back on every toggle, both wrapped in try/catch so a blocked or
331	   * full localStorage never breaks navigation.
332	   */
333	  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});
