335	    try {
336	      const raw = localStorage.getItem("nxeon.admin.navCollapsed");
337	      if (raw) setCollapsedGroups(JSON.parse(raw));
338	    } catch {}
339	  }, []);
340	  function toggleGroup(key: string) {
341	    setCollapsedGroups((prev) => {
342	      const next = { ...prev, [key]: !prev[key] };
343	      try {
344	        localStorage.setItem("nxeon.admin.navCollapsed", JSON.stringify(next));
345	      } catch {}
346	      return next;
347	    });
348	  }
349	
350	  /**
351	   * Publish the rail's current width so `position: fixed` chrome outside this
352	   * subtree can sit beside it instead of guessing.
353	   *
354	   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
355	   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
