14	/**
15	 * Inbound-transfer status card for the domain detail page.
16	 *
17	 * Deliberately blunt about the two things customers get wrong: a transfer is
18	 * not instant (5-7 days), and it will silently expire unless they approve the
19	 * email their OLD registrar sends them.
20	 */
21	export function TransferInStatusCard({
22	  domainId,
23	  domainName,
24	  status,
25	  transferStatus,
26	  transferStatusLabel,
27	  transferEmail,
28	  transferStartedAt,
29	  priceCents,
30	  error,
31	}: {
32	  domainId: string;
33	  domainName: string;
34	  status: string;
35	  transferStatus: string | null;
36	  transferStatusLabel: string | null;
37	  transferEmail: string | null;
38	  transferStartedAt: string | null;
39	  priceCents: number;
40	  error: string | null;
41	}) {
42	  const router = useRouter();
43	  const [note, setNote] = useState<string | null>(null);
44	  const [cancelError, setCancelError] = useState<string | null>(null);
45	  const [confirming, setConfirming] = useState(false);
46	  const [pending, start] = useTransition();
47	
48	  const started = transferStartedAt ? new Date(transferStartedAt) : null;
49	  const age = daysSince(started);
50	  const pendingTransfer = status === "TRANSFER_PENDING";
51	
52	  function doCancel() {
53	    start(async () => {
54	      setCancelError(null);
55	      setNote(null);
56	      const res = await cancelTransferIn(domainId);
57	      if (res?.error) setCancelError(res.error);
58	      else {
59	        setNote(res.note ?? "Transfer cancelled.");
60	        setConfirming(false);
61	        router.refresh();
62	      }
63	    });
64	  }
