66	  if (status === "TRANSFER_FAILED") {
67	    return (
68	      <div className="card border-red-500/30 bg-red-500/[0.04]">
69	        <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
70	          <h2 className="font-semibold text-red-200">Transfer did not complete</h2>
71	          <Badge tone="red">{transferStatus ?? "failed"}</Badge>
