87	      </div>
88	    );
89	  }
90	
91	  if (!pendingTransfer) return null;
92	
93	  return (
94	    <div className="card border-amber-500/30 bg-amber-500/[0.05]">
95	      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
96	        <h2 className="font-semibold text-amber-100">Transfer in progress</h2>
97	        <Badge tone="amber">{transferStatus ?? "pending"}</Badge>
98	      </div>
99	
100	      <p className="text-sm text-slate-200">
101	        {transferStatusLabel ?? "Waiting on the registrar."}
102	      </p>
103	
104	      <div className="mt-4 rounded-xl border border-white/10 bg-navy-950/50 p-4">
105	        <p className="text-sm font-semibold text-white">What you need to do</p>
106	        <p className="mt-1 text-sm text-slate-300">
107	          Your <span className="font-semibold text-white">current</span> registrar sends a confirmation email
108	          to the domain&apos;s registered contact
109	          {transferEmail ? (
110	            <>
111	              {" "}
112	              — we&apos;re told that&apos;s <span className="font-mono text-slate-200">{transferEmail}</span>
113	            </>
114	          ) : null}
115	          . You have to open it and approve the transfer. Until you do, nothing happens, and the request
116	          eventually expires on its own.
117	        </p>
118	        <p className="mt-2 text-xs text-slate-400">
119	          Check spam too — these emails come from the losing registrar, not from us.
120	        </p>
121	      </div>
122	
123	      <dl className="mt-4 space-y-2 text-sm">
124	        <div className="flex justify-between">
125	          <dt className="text-slate-400">Started</dt>
