166	                {pending ? "Contacting registrar…" : "Yes, cancel it"}
167	              </button>
168	              <button
169	                type="button"
170	                className="btn-ghost"
171	                disabled={pending}
172	                onClick={() => setConfirming(false)}
173	              >
174	                Keep it going
175	              </button>
176	            </div>
177	          </div>
178	        )}
179	        {note && <p className="mt-3 text-sm text-emerald-300">{note}</p>}
180	        {cancelError && <p className="mt-3 text-sm text-red-400">{cancelError}</p>}
181	      </div>
182	    </div>
183	  );
184	}
