13	/**
14	 * SSL certificate manager for /dashboard/ssl.
15	 *
16	 * Replaces SslManager, whose table could not tell the truth about a certificate:
17	 * it rendered `expiresAt` as a bare date with no notion of whether that date had
18	 * passed (an expired cert kept a green pulsing ACTIVE dot while every visitor got
19	 * NET::ERR_CERT_DATE_INVALID), showed a mid-issuance row as the grey STOPPED dot,
20	 * gave a queued request no explanation at all — one sat "pending" for 13 minutes
21	 * behind another tenant's MIGRATE with nothing on screen to say so — and hard-
22	 * disabled Delete on any ISSUING row, stranding rows a worker restart had
23	 * orphaned.
24	 *
25	 * Every status here is derived from an observed value: `expiresAt` is the
26	 * notAfter read off the certificate (by openssl on the box at issuance, then by a
27	 * TLS read-back of :443 in the renewal sweep), and `lastError` on a non-FAILED
28	 * row means "the certificate exists but something about it is wrong" — most often
29	 * that certbot obtained it in standalone mode and nothing installed it.
30	 */
31	
32	/** Where a still-unfinished request sits in the platform's single serial queue. */
33	export type QueueInfo = {
34	  /** running = certbot is executing; queued = waiting its turn; none = no job at all. */
35	  state: "running" | "queued" | "none";
36	  /** 1 = next to run. Only meaningful when state === "queued". */
37	  position: number;
38	  aheadCount: number;
39	  queuedAtIso: string;
40	  /** The job holding the worker right now, if any. */
41	  blocking: { type: string; mine: boolean } | null;
42	};
43	
44	export type CertRow = {
45	  id: string;
46	  domain: string;
47	  status: string;
48	  issuer: string;
49	  autoRenew: boolean;
50	  serverName: string | null;
51	  issuedAt: string | null;
52	  /** The observed notAfter. Never a computed guess — null means "not verified". */
53	  expiresAt: string | null;
54	  lastError: string | null;
55	  queue: QueueInfo | null;
56	};
