60	const DAY_MS = 86_400_000;
61	
62	function fmtDate(iso: string | null): string {
63	  return iso ? new Date(iso).toISOString().slice(0, 10) : "—";
64	}
65	
66	function daysUntil(iso: string | null): number | null {
67	  if (!iso) return null;
68	  return Math.floor((new Date(iso).getTime() - Date.now()) / DAY_MS);
69	}
70	
71	function ago(iso: string): string {
72	  const mins = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60_000));
73	  if (mins < 1) return "just now";
74	  if (mins === 1) return "1 minute ago";
75	  if (mins < 60) return `${mins} minutes ago`;
76	  const hrs = Math.round(mins / 60);
77	  return hrs === 1 ? "1 hour ago" : `${hrs} hours ago`;
78	}
