91	  SNAPSHOT_ROLLBACK: "snapshot rollback",
92	  SSL_ISSUE: "certificate request",
93	  WEBSITE_SSL: "website SSL setup",
94	  GAME_UPDATE: "game server update",
95	  APP_INSTALL: "app install",
96	};
