186	/**
187	 * Why this exists: "pending" with a spinner is indistinguishable from "broken".
188	 * The worker claims one QUEUED job at a time platform-wide, ordered by creation,
189	 * so a certificate really can wait behind another customer's long migration.
190	 * Saying so — with a position and how long it has waited — is the difference
191	 * between a wait and an outage.
192	 */
193	function QueueNote({ q }: { q: QueueInfo | null }) {
194	  if (!q) return null;
195	
196	  if (q.state === "none") {
197	    return (
198	      <p className="mt-1 text-xs text-amber-400">
199	        No worker job is attached to this request, so nothing is running. It is cleared automatically
200	        within 15 minutes — or delete it and try again now.
201	      </p>
202	    );
203	  }
204	
205	  if (q.state === "running") {
206	    return (
207	      <p className="mt-1 text-xs text-slate-400">
208	        certbot is running on your server now — started {ago(q.queuedAtIso)}.
209	      </p>
210	    );
211	  }
212	
213	  const blocking = q.blocking
214	    ? `${q.blocking.mine ? "your" : "another customer's"} ${jobLabel(q.blocking.type)}`
215	    : "the job currently running";
216	
217	  return (
218	    <p className="mt-1 text-xs text-slate-400">
219	      Waiting for other work to finish —{" "}
220	      {q.aheadCount === 0 ? "next in line" : `position ${q.position} in the platform queue`}. Jobs run
221	      one at a time and {blocking} is ahead of it. Queued {ago(q.queuedAtIso)}. Nothing is wrong.
222	    </p>
223	  );
224	}
