226	function StatusCell({ c }: { c: CertRow }) {
227	  const left = daysUntil(c.expiresAt);
228	
229	  if (c.status === "PENDING") {
230	    return (
231	      <div>
232	        <StatusDot status="QUEUED" label={c.queue?.state === "none" ? "not started" : "queued"} />
233	        <QueueNote q={c.queue} />
234	      </div>
235	    );
236	  }
237	
238	  if (c.status === "ISSUING") {
239	    return (
240	      <div>
241	        {/* PROVISIONING, not ISSUING: `statusColors` has no ISSUING entry, so the
242	            literal status falls back to STOPPED's neutral grey and a certificate
243	            mid-issuance reads as "nothing happening". */}
244	        <StatusDot status="PROVISIONING" label="issuing" />
245	        {left !== null && left >= 0 && (
246	          <p className="mt-1 text-xs text-slate-400">
247	            Renewing. Your current certificate stays valid for {left} more day{left === 1 ? "" : "s"}.
248	          </p>
249	        )}
250	        <QueueNote q={c.queue} />
251	      </div>
252	    );
253	  }
254	
255	  if (c.status === "EXPIRED") {
256	    return (
257	      <div>
258	        <StatusDot status="FAILED" label="expired" />
259	        <p className="mt-1 text-xs text-red-400">
260	          {left !== null
261	            ? `Expired ${Math.abs(left)} day${Math.abs(left) === 1 ? "" : "s"} ago — visitors see a browser security warning.`
262	            : "Visitors see a browser security warning until a new certificate is installed."}
263	        </p>
264	      </div>
265	    );
266	  }
267	
268	  if (c.status === "ACTIVE") {
269	    // Never a plain green dot unless we have a real observed expiry in the future
270	    // and nothing has flagged a problem with the certificate.
271	    if (c.expiresAt === null) {
272	      return (
273	        <div>
274	          <StatusDot status="PENDING" label="unverified" />
275	          <p className="mt-1 text-xs text-amber-400">
276	            No expiry date has been read back from this certificate, so we cannot confirm it is valid.
277	          </p>
278	        </div>
279	      );
280	    }
281	    if (c.lastError) {
282	      return (
283	        <div>
284	          {/* Amber on purpose: the certificate exists, but the site is not
285	              necessarily serving it. Green here is the lie this page fixes. */}
286	          <StatusDot status="COMPLETED_WITH_ISSUES" label="issued — needs attention" />
287	        </div>
288	      );
289	    }
290	    return (
291	      <div className="flex flex-wrap items-center gap-2">
292	        <StatusDot status="ACTIVE" label="active" />
293	        {left !== null && (
294	          <Badge tone={left <= 7 ? "red" : left <= 21 ? "amber" : "green"}>
295	            {left} day{left === 1 ? "" : "s"} left
296	          </Badge>
297	        )}
298	      </div>
299	    );
300	  }
301	
302	  // FAILED (and anything unrecognised).
303	  return <StatusDot status={c.status} />;
304	}
