324	  // ISSUING by a dead worker must be clearable, or the customer can never
325	  // request that domain again.
326	  const issuingNow = cert.status === "ISSUING" && cert.queue?.state === "running";
327	  const canRenew = ["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status);
328	
329	  return (
330	    <div className="flex flex-col items-end gap-1.5">
331	      <div className="flex items-center gap-2">
332	        <button
333	          type="button"
334	          role="switch"
