337	          disabled={pending}
338	          onClick={() => run(() => toggleAutoRenew(cert.id))}
339	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
340	            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
341	          } ${pending ? "opacity-60" : ""}`}
342	        >
343	          <span
344	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
345	              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
346	            }`}
347	          />
348	        </button>
349	        {canRenew && (
350	          <button
351	            className="btn-ghost px-3 py-1 text-xs"
352	            disabled={pending}
353	            onClick={() =>
