45	/** Link to the OAuth start route, carrying what to do once connected. */
46	export function cloudflareStartHref(opts: {
47	  intent: CfIntentKind;
48	  id?: string;
49	  host?: string;
50	  next: string;
51	}): string {
52	  const sp = new URLSearchParams({ intent: opts.intent, next: opts.next });
53	  if (opts.id) sp.set("id", opts.id);
54	  if (opts.host) sp.set("host", opts.host);
55	  return `/api/integrations/cloudflare/start?${sp.toString()}`;
