58	/**
59	 * Banner for the `?cf=` / `?cfdns=` flags the OAuth callback appends when it
60	 * lands the customer back on their page. Reads them from the URL on mount (no
61	 * useSearchParams, so no Suspense boundary needed) and tidies the URL afterwards.
62	 */
63	export function CloudflareResultBanner() {
64	  const [msg, setMsg] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
65	
66	  useEffect(() => {
67	    const sp = new URLSearchParams(window.location.search);
68	    const cf = sp.get("cf");
69	    const cfdns = sp.get("cfdns");
70	    const detail = sp.get("cfmsg");
71	    if (!cf && !cfdns) return;
72	
73	    if (cf === "error") {
74	      setMsg({ tone: "error", text: detail || "Couldn't connect Cloudflare." });
75	    } else if (cfdns === "error") {
76	      setMsg({
77	        tone: "error",
78	        text: `Cloudflare connected, but the DNS record wasn't added: ${detail || "unknown error"}`,
79	      });
80	    } else if (cfdns === "ok") {
81	      setMsg({ tone: "ok", text: `Cloudflare connected. ${detail || "DNS records added."}` });
82	    } else if (cf === "connected") {
83	      setMsg({ tone: "ok", text: "Cloudflare connected." });
84	    }
85	
86	    // Drop our flags from the address bar so a refresh doesn't re-show the banner.
87	    ["cf", "cfdns", "cfmsg"].forEach((k) => sp.delete(k));
88	    const qs = sp.toString();
89	    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
90	  }, []);
91	
92	  if (!msg) return null;
93	  return (
94	    <div
95	      className={`mb-4 rounded-xl border px-3 py-2 text-sm ${
96	        msg.tone === "ok"
97	          ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
98	          : "border-amber-500/30 bg-amber-500/10 text-amber-200"
99	      }`}
100	    >
101	      {msg.text}
102	    </div>
103	  );
104	}
