644	/**
645	 * Why a subscription needs the customer's attention right now — surfaced so it
646	 * can be sorted to the top and auto-expanded instead of getting the same visual
647	 * weight (and default-collapsed treatment) as one that's already fully set up.
648	 */
649	function attentionReason(sub: SubscriptionRow): "dns" | "failed" | null {
650	  if (sub.external && !sub.verified) return "dns";
651	  if (sub.mailboxes.some((m) => m.status === "FAILED")) return "failed";
652	  return null;
653	}
654	
655	/** attention: needs a customer action · active: set up and has mailboxes ·
656	 *  empty: nothing blocking, just hasn't had a mailbox added yet. */
657	function categoryOf(sub: SubscriptionRow): "attention" | "active" | "empty" {
658	  if (attentionReason(sub)) return "attention";
659	  return sub.mailboxes.length === 0 ? "empty" : "active";
660	}
661	
662	const CATEGORY_RANK: Record<ReturnType<typeof categoryOf>, number> = {
663	  attention: 0,
664	  active: 1,
665	  empty: 2,
666	};
667	
668	/** Same pill-filter convention as ServersList.tsx — active/count chips, click
669	 *  again to clear back to "All". */
670	function FilterChip({
671	  label,
672	  count,
673	  active,
674	  onClick,
675	}: {
676	  label: string;
677	  count: number;
678	  active: boolean;
679	  onClick: () => void;
680	}) {
681	  return (
682	    <button
683	      type="button"
684	      onClick={onClick}
685	      className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
686	        active
687	          ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
688	          : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
689	      }`}
690	    >
691	      {label} · {count}
692	    </button>
693	  );
694	}
695	
696	type SubFilter = "ALL" | "attention" | "active" | "empty";
697	
698	/**
699	 * The reorganized subscriptions list — replaces "every subscription fully
700	 * expanded, in one long column" with:
701	 *   - filter chips (ServersList's established pill convention) so a customer
702	 *     with many domains can jump straight to the ones that need setup;
703	 *   - a domain search box, once there are enough subscriptions for one to earn
704	 *     its place on screen;
705	 *   - subscriptions needing attention (unverified DNS, a failed mailbox)
706	 *     sorted first; fully-empty "not set up yet" ones sorted last so they
707	 *     don't take the same prime real estate as an active domain.
708	 * Each subscription still renders through SubscriptionCard — nothing about
709	 * the underlying data or actions changes, only default expand/collapse and
710	 * ordering.
711	 */
712	function SubscriptionsList({ subscriptions }: { subscriptions: SubscriptionRow[] }) {
713	  const [query, setQuery] = useState("");
714	  const [filter, setFilter] = useState<SubFilter>("ALL");
715	
716	  const categorized = useMemo(
717	    () => subscriptions.map((sub) => ({ sub, category: categoryOf(sub) })),
718	    [subscriptions],
719	  );
720	
721	  const counts = useMemo(() => {
722	    const c = { attention: 0, active: 0, empty: 0 };
723	    for (const { category } of categorized) c[category]++;
724	    return c;
725	  }, [categorized]);
726	
727	  const q = query.trim().toLowerCase();
728	  const searched = q ? categorized.filter(({ sub }) => sub.domainName.toLowerCase().includes(q)) : categorized;
729	  const filtered = filter === "ALL" ? searched : searched.filter((x) => x.category === filter);
730	  // Array.prototype.sort is stable (ES2019+), so this only groups — it never
731	  // reorders two subscriptions within the same category relative to each other.
732	  const ordered = [...filtered].sort((a, b) => CATEGORY_RANK[a.category] - CATEGORY_RANK[b.category]);
733	
734	  // A handful of subscriptions isn't the clutter problem this is solving —
735	  // showing search/filter chrome over 2-3 cards would just be more clutter.
736	  const showToolbar = subscriptions.length > 3;
737	
738	  return (
739	    <div className="space-y-4">
740	      {showToolbar && (
741	        <div className="flex flex-wrap items-center gap-2">
742	          <FilterChip label="All" count={subscriptions.length} active={filter === "ALL"} onClick={() => setFilter("ALL")} />
743	          {counts.attention > 0 && (
744	            <FilterChip
745	              label="Needs attention"
746	              count={counts.attention}
747	              active={filter === "attention"}
748	              onClick={() => setFilter((f) => (f === "attention" ? "ALL" : "attention"))}
749	            />
750	          )}
751	          {counts.active > 0 && (
752	            <FilterChip
753	              label="Active"
754	              count={counts.active}
755	              active={filter === "active"}
756	              onClick={() => setFilter((f) => (f === "active" ? "ALL" : "active"))}
