1	"use client";
2	
3	// Dashboard-layer compose provider.
4	//
5	// The composer used to live INSIDE the mail page (MailClient rendered <Composer>
6	// inline). That had two problems this provider fixes:
7	//
8	//  1. `position: fixed` on the composer was scoped to the mail client's own box,
9	//     not the viewport, because an ancestor carried a `backdrop-filter`
10	//     (`backdrop-blur-md`) — and a backdrop-filtered ancestor becomes the
11	//     containing block for its fixed descendants. Portalling the composer to
12	//     `document.body` (no filtered/transformed ancestor) makes `fixed` mean the
13	//     real viewport again, so the panel is ALWAYS visible regardless of scroll.
14	//
15	//  2. A composer rendered by a page is torn down the instant you navigate away,
16	//     losing an in-progress draft. This provider is mounted once at the shell
17	//     level (see components/portal/Shell.tsx), which the App Router keeps mounted
18	//     across route changes — so the composer, its draft, and a minimized dock
19	//     survive navigating to any other dashboard page until it's sent or discarded.
20	//
21	// It holds the single source of truth for the open draft and the minimized flag,
22	// owns the actual send (so a message can be sent from any page, not just the mail
23	// app), and renders the Composer through a portal. Mail pages drive it purely
24	// through `useCompose()`.
25	
26	import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
27	import { createPortal } from "react-dom";
28	import type { SendPayload } from "@/lib/mail/types";
29	import { sendMessage } from "@/lib/actions-mail";
30	import { Composer, type ComposeDraft } from "./Composer";
31	import { Icon } from "./util";
32	
33	type ComposeContextValue = {
34	  /** Open (or replace) the composer with a fully-built draft, un-minimized. */
35	  open: (draft: ComposeDraft) => void;
36	  minimize: () => void;
37	  restore: () => void;
38	  close: () => void;
39	  isOpen: boolean;
40	  isMinimized: boolean;
41	};
42	
43	const ComposeContext = createContext<ComposeContextValue | null>(null);
44	
45	/** Access the shell-level composer. Must be called under a <ComposeProvider>. */
46	export function useCompose(): ComposeContextValue {
47	  const ctx = useContext(ComposeContext);
48	  if (!ctx) throw new Error("useCompose must be used within a ComposeProvider");
49	  return ctx;
50	}
51	
52	/** Fired on the window after a message is sent, so a mounted MailClient can
53	 *  refresh its Sent view without the provider knowing anything about it. */
54	export const MAIL_SENT_EVENT = "nxeon:mail-sent";
55	
56	export function ComposeProvider({ children }: { children: React.ReactNode }) {
57	  const [draft, setDraft] = useState<ComposeDraft | null>(null);
58	  const [minimized, setMinimized] = useState(false);
59	  const [toast, setToast] = useState<string | null>(null);
60	  // Portals need a DOM target — only available after mount (never during SSR).
61	  const [mounted, setMounted] = useState(false);
62	  useEffect(() => setMounted(true), []);
63	
64	  const open = useCallback((d: ComposeDraft) => {
65	    setDraft(d);
66	    setMinimized(false);
67	  }, []);
68	  const minimize = useCallback(() => setMinimized(true), []);
69	  const restore = useCallback(() => setMinimized(false), []);
70	  const close = useCallback(() => {
71	    setDraft(null);
72	    setMinimized(false);
73	  }, []);
74	
75	  // The provider owns the send so it works from ANY page (the composer can be
76	  // sent after navigating away from the mail app). It re-uses the same server
77	  // action MailClient did; the mailbox to send from rides along on the draft.
78	  const handleSend = useCallback(async (payload: SendPayload, mailboxAddress?: string) => {
79	    const res = await sendMessage(payload, mailboxAddress);
80	    if (res && res.ok === false) throw new Error(res.error || "The mail server rejected the message.");
81	    setToast("Message sent.");
82	    try {
83	      window.dispatchEvent(new CustomEvent(MAIL_SENT_EVENT));
84	    } catch {
85	      /* SSR / no window — nothing to refresh */
86	    }
87	  }, []);
88	
89	  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
90	  useEffect(() => {
91	    if (!toast) return;
92	    if (toastTimer.current) clearTimeout(toastTimer.current);
93	    toastTimer.current = setTimeout(() => setToast(null), 2600);
94	    return () => {
95	      if (toastTimer.current) clearTimeout(toastTimer.current);
96	    };
97	  }, [toast]);
98	
99	  const value: ComposeContextValue = {
100	    open,
101	    minimize,
102	    restore,
103	    close,
104	    isOpen: !!draft,
105	    isMinimized: minimized,
106	  };
107	
108	  return (
109	    <ComposeContext.Provider value={value}>
110	      {children}
111	      {mounted && draft
112	        ? createPortal(
113	            <Composer
114	              draft={draft}
115	              minimized={minimized}
116	              onMinimize={minimize}
117	              onRestore={restore}
118	              onClose={close}
119	              onSend={handleSend}
120	            />,
121	            document.body,
122	          )
123	        : null}
124	      {mounted && toast
125	        ? createPortal(
126	            <div className="pointer-events-none fixed bottom-4 left-1/2 z-[70] -translate-x-1/2" role="status" aria-live="polite">
127	              <div className="glass flex items-center gap-2 px-4 py-2.5 text-sm text-slate-100 shadow-2xl animate-fade-up">
128	                <span className="text-brand-300"><Icon.mail size={15} /></span>
129	                {toast}
130	              </div>
131	            </div>,
132	            document.body,
133	          )
134	        : null}
135	    </ComposeContext.Provider>
136	  );
137	}
