274	/** Renders the email body. HTML is dropped into a sandboxed iframe with
275	 *  `allow-same-origin` but crucially NO `allow-scripts`, so sender scripts still
276	 *  never execute — allow-same-origin only lets the PARENT read the inner document
277	 *  to auto-size the frame to its full content height. Plaintext falls back to a
278	 *  pre block. */
279	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
280	  const ref = useRef<HTMLIFrameElement>(null);
281	  const observerRef = useRef<ResizeObserver | null>(null);
282	  const [height, setHeight] = useState(MIN_BODY_HEIGHT);
283	
284	  const doc = html
285	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
286	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
287	        body{padding:16px;}
288	        img{max-width:100%;height:auto;}
289	        a{color:#5f2ee8;}
290	        table{max-width:100%;}
291	        pre{white-space:pre-wrap;}
292	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
293	      </style></head><body>${html}</body></html>`
294	    : null;
295	
296	  // Autosize: with sandbox="allow-same-origin" (and still NO allow-scripts, so
297	  // sender scripts stay inert) the parent can read the inner document and grow the
298	  // frame to its full content height — the whole email renders in the page flow
299	  // (the reading pane scrolls, the frame itself never does), so tall mail is no
300	  // longer clipped. Reset to the min height when the body changes.
301	  useEffect(() => {
302	    setHeight(html ? MIN_BODY_HEIGHT : 0);
303	  }, [html]);
304	
305	  // Measure the rendered document and size the frame to it (plus a small buffer),
306	  // clamped so short mail isn't a giant box and runaway content can't explode.
307	  const measure = useCallback(() => {
308	    const cdoc = ref.current?.contentDocument;
309	    if (!cdoc) return;
310	    const h = Math.max(
311	      cdoc.documentElement?.scrollHeight ?? 0,
312	      cdoc.body?.scrollHeight ?? 0,
313	    );
314	    if (h > 0) {
315	      setHeight(Math.min(MAX_BODY_HEIGHT, Math.max(MIN_BODY_HEIGHT, Math.ceil(h) + BODY_HEIGHT_BUFFER)));
316	    }
317	  }, []);
318	
319	  // Tear down the body observer on unmount / body swap.
320	  useEffect(() => () => { observerRef.current?.disconnect(); observerRef.current = null; }, []);
321	
322	  // On each (re)load: measure once, then keep re-measuring as late layout settles
323	  // — image decode, web-font swaps, async reflows. A ResizeObserver on the inner
324	  // <body> catches most of it; a few delayed passes and per-image load handlers
325	  // cover the rest.
326	  const handleLoad = useCallback(() => {
327	    measure();
328	    const cdoc = ref.current?.contentDocument;
329	    [60, 200, 500, 1200].forEach((ms) => window.setTimeout(measure, ms));
330	    observerRef.current?.disconnect();
331	    observerRef.current = null;
332	    if (cdoc?.body && typeof ResizeObserver !== "undefined") {
333	      const ro = new ResizeObserver(() => measure());
334	      ro.observe(cdoc.body);
335	      observerRef.current = ro;
336	    }
337	    cdoc?.querySelectorAll("img").forEach((img) => {
338	      if (!img.complete) img.addEventListener("load", measure, { once: true });
339	    });
340	  }, [measure]);
341	
342	  // Render the body from a blob: URL rather than `srcDoc`. A `sandbox=""` srcdoc
343	  // frame loads as `about:srcdoc`, which our strict CSP `frame-src` refuses
344	  // ("This content is blocked…"). A blob: URL is a real same-origin URL that
345	  // `frame-src blob:` matches, so the frame loads; it still inherits the app CSP
346	  // (img-src https: lets email images through, scripts stay blocked) and stays
347	  // fully sandboxed. Revoked when the body changes / unmounts.
348	  const [bodyUrl, setBodyUrl] = useState<string | null>(null);
349	  useEffect(() => {
350	    if (!doc) {
351	      setBodyUrl(null);
352	      return;
353	    }
354	    const url = URL.createObjectURL(new Blob([doc], { type: "text/html" }));
355	    setBodyUrl(url);
356	    return () => URL.revokeObjectURL(url);
357	  }, [doc]);
358	
359	  if (doc && bodyUrl) {
360	    return (
361	      <iframe
362	        ref={ref}
363	        // allow-same-origin lets the PARENT read contentDocument to auto-size the
364	        // frame; allow-scripts is deliberately omitted so sender scripts never run.
365	        sandbox="allow-same-origin"
366	        src={bodyUrl}
367	        title="Message content"
368	        onLoad={handleLoad}
369	        scrolling="no"
370	        className="w-full rounded-xl border border-white/[0.06] bg-white"
371	        style={{ height, minHeight: MIN_BODY_HEIGHT }}
372	      />
373	    );
374	  }
375	
376	  if (text && text.trim()) {
377	    return (
378	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
379	        {text}
380	      </pre>
381	    );
382	  }
383	
384	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
385	}
