3	/* -------------------------------------------------------------------------- */
4	/* Presentation helpers shared across the mail UI                              */
5	/* -------------------------------------------------------------------------- */
6	
7	/** Display name for an address: prefer the friendly name, fall back to the
8	 *  local part of the email (before the @). */
9	export function displayName(a?: MailAddress | null): string {
10	  if (!a) return "Unknown";
11	  if (a.name && a.name.trim()) return a.name.trim();
12	  const at = a.address.indexOf("@");
13	  return at > 0 ? a.address.slice(0, at) : a.address || "Unknown";
14	}
15	
16	/** Up-to-two-letter initials from a name or address. */
17	export function initials(a?: MailAddress | null): string {
18	  const name = displayName(a);
19	  const parts = name.replace(/[^\p{L}\p{N} ]/gu, " ").trim().split(/\s+/).filter(Boolean);
20	  if (parts.length === 0) return "?";
21	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
22	  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
23	}
24	
25	/** Deterministic on-brand gradient for an avatar, derived from the address so a
26	 *  given sender always gets the same colour. Hues are pulled toward the violet /
27	 *  blue / cyan Nxeon range with a couple of warm accents for variety. */
28	const AVATAR_GRADIENTS = [
29	  "from-brand-500 to-accent-blue",
30	  "from-accent-blue to-brand-400",
31	  "from-brand-400 to-fuchsia-500",
32	  "from-accent-cyan to-accent-blue",
33	  "from-violet-500 to-brand-600",
34	  "from-sky-500 to-brand-500",
35	  "from-brand-600 to-violet-400",
36	  "from-emerald-500 to-accent-cyan",
37	  "from-rose-500 to-brand-500",
38	  "from-amber-500 to-rose-500",
39	];
40	
41	export function avatarGradient(seed: string): string {
42	  let h = 0;
43	  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
44	  return AVATAR_GRADIENTS[h % AVATAR_GRADIENTS.length];
45	}
46	
47	/** Compact list timestamp: relative for very recent ("now", "5m", "3h"), time
48	 *  for the rest of today, "Mon" for this week, else a short date. */
49	export function shortDate(iso: string): string {
50	  const d = new Date(iso);
51	  if (Number.isNaN(d.getTime())) return "";
52	  const now = new Date();
53	  const diffMin = (now.getTime() - d.getTime()) / 60_000;
54	  const sameDay =
55	    d.getFullYear() === now.getFullYear() &&
56	    d.getMonth() === now.getMonth() &&
57	    d.getDate() === now.getDate();
58	  if (sameDay) {
59	    if (diffMin >= 0 && diffMin < 1) return "now";
60	    if (diffMin >= 1 && diffMin < 60) return `${Math.floor(diffMin)}m`;
61	    if (diffMin >= 60 && diffMin < 720) return `${Math.floor(diffMin / 60)}h`;
62	    return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
63	  }
64	  const diffDays = (now.getTime() - d.getTime()) / 86_400_000;
65	  if (diffDays < 7 && diffDays > 0) return d.toLocaleDateString([], { weekday: "short" });
66	  const sameYear = d.getFullYear() === now.getFullYear();
67	  return d.toLocaleDateString([], sameYear ? { month: "short", day: "numeric" } : { month: "short", day: "numeric", year: "2-digit" });
68	}
69	
70	/** Section header for a day group in the message list: "Today", "Yesterday",
71	 *  the weekday within the past week, else a full-ish date. */
72	export function dayLabel(iso: string): string {
73	  const d = new Date(iso);
74	  if (Number.isNaN(d.getTime())) return "Earlier";
75	  const now = new Date();
76	  const startOfDay = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
77	  const diffDays = Math.round((startOfDay(now) - startOfDay(d)) / 86_400_000);
78	  if (diffDays <= 0) return "Today";
79	  if (diffDays === 1) return "Yesterday";
80	  if (diffDays < 7) return d.toLocaleDateString([], { weekday: "long" });
81	  const sameYear = d.getFullYear() === now.getFullYear();
82	  return d.toLocaleDateString([], sameYear ? { month: "long", day: "numeric" } : { month: "long", day: "numeric", year: "numeric" });
83	}
84	
85	/** Verbose header timestamp for the reading pane. */
86	export function fullDate(iso: string): string {
87	  const d = new Date(iso);
88	  if (Number.isNaN(d.getTime())) return "";
89	  return d.toLocaleString([], {
90	    weekday: "short",
91	    month: "short",
92	    day: "numeric",
93	    year: "numeric",
94	    hour: "numeric",
95	    minute: "2-digit",
96	  });
97	}
98	
99	export function fmtBytesShort(b: number): string {
100	  if (!b || b <= 0) return "0 B";
101	  const units = ["B", "KB", "MB", "GB", "TB"];
102	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
103	  return `${(b / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
104	}
105	
106	/** Format a list of addresses as "Alice, Bob +2". */
107	export function joinAddresses(list: MailAddress[], max = 3): string {
108	  if (!list || list.length === 0) return "—";
109	  const names = list.slice(0, max).map(displayName);
110	  const extra = list.length - max;
111	  return names.join(", ") + (extra > 0 ? ` +${extra}` : "");
112	}
