1	// Pure recipient-chip parsing/validation for the mail composer. No React, no DOM
2	// APIs — just string work — so it runs identically in the browser (the chip
3	// inputs) and under `node:test`.
4	//
5	// The composer's To/Cc fields are chip inputs: the customer types an address and
6	// presses Enter/comma, or pastes a whole comma/space/newline-separated list, and
7	// each valid address becomes a removable chip. The send payload the server
8	// (`lib/actions-mail.ts` → `parseRecipients`) expects is a single
9	// comma-separated string, so `recipientsToField` re-joins the chips into exactly
10	// that shape. Validation is SOFT: a pasted list is split, the valid addresses
11	// become chips, and anything that isn't an address is handed back as `invalid`
12	// so the UI can surface it without dropping the customer's typing on the floor.
13	
14	// Address SHAPE only (same lax rule the server uses). Real deliverability is the
15	// mail server's job; this just keeps obvious non-addresses out of the chips.
16	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
17	
18	/** True when `addr` has the shape of an email address. */
19	export function isValidEmail(addr: string): boolean {
20	  return EMAIL_RE.test((addr || "").trim());
21	}
22	
23	/** Pull the bare address out of a token, tolerating the `Name <addr>` form. */
24	export function extractAddress(token: string): string {
25	  const m = (token || "").match(/<([^>]+)>/);
26	  return (m ? m[1] : token).trim();
27	}
28	
29	export type ParsedRecipients = { valid: string[]; invalid: string[] };
30	
31	/**
32	 * Split a raw string into recipient tokens and classify each. Splitting happens
33	 * on commas, semicolons and newlines first (so a `Name <addr>` piece stays
34	 * whole), then a bracket-less piece is further split on whitespace so a
35	 * space-separated paste like `a@x.com b@y.com` still becomes two chips. Valid
36	 * addresses are de-duplicated case-insensitively, keeping first-seen order and
37	 * the original casing; everything else lands in `invalid`.
38	 */
39	export function parseRecipientInput(raw: string): ParsedRecipients {
40	  const pieces = (raw || "")
41	    .split(/[,;\n\r]+/)
42	    .map((s) => s.trim())
43	    .filter(Boolean);
44	
45	  const tokens: string[] = [];
46	  for (const piece of pieces) {
47	    // A `Name <addr>` piece can contain spaces — keep it whole. A bracket-less
48	    // piece may itself be a space-separated list, so split it.
49	    if (piece.includes("<")) tokens.push(piece);
50	    else tokens.push(...piece.split(/\s+/).filter(Boolean));
51	  }
52	
53	  const valid: string[] = [];
54	  const invalid: string[] = [];
55	  const seen = new Set<string>();
56	  for (const tok of tokens) {
57	    const addr = extractAddress(tok);
58	    if (isValidEmail(addr)) {
59	      const key = addr.toLowerCase();
60	      if (!seen.has(key)) {
61	        seen.add(key);
62	        valid.push(addr);
63	      }
64	    } else {
65	      invalid.push(tok);
66	    }
67	  }
68	  return { valid, invalid };
69	}
70	
71	/**
72	 * Merge the addresses parsed out of `raw` into an existing chip list, de-duping
73	 * case-insensitively against what's already there. Returns the combined chips
74	 * and any tokens that weren't valid addresses (for the caller to keep in the
75	 * input buffer / flag).
76	 */
77	export function addRecipients(existing: string[], raw: string): { chips: string[]; invalid: string[] } {
78	  const { valid, invalid } = parseRecipientInput(raw);
79	  const seen = new Set(existing.map((e) => e.toLowerCase()));
80	  const chips = existing.slice();
81	  for (const v of valid) {
82	    const key = v.toLowerCase();
83	    if (!seen.has(key)) {
84	      seen.add(key);
85	      chips.push(v);
86	    }
87	  }
88	  return { chips, invalid };
89	}
90	
91	/**
92	 * Serialise chips into the comma-separated string the send payload carries.
93	 * Mirrors what the server's `parseRecipients` splits back apart, so a chip list
94	 * round-trips to the exact addresses that get sent.
95	 */
96	export function recipientsToField(chips: string[]): string {
97	  return chips.join(", ");
98	}
