842	/* Live rule status (auto-reply + forwarding)                                  */
843	/* -------------------------------------------------------------------------- */
844	
845	/**
846	 * Read back what the MAIL SERVER is actually running for this mailbox.
847	 *
848	 * WHY this exists: both of these sections used to carry a hardcoded amber
849	 * "…is rolling out — until then these settings are stored but not sent"
850	 * notice. Auto-reply and forwarding really were store-only then; they are real
851	 * sieve now, so that fixed sentence had become a lie in the other direction —
852	 * telling a customer their working out-of-office does nothing. Neither the old
853	 * notice nor a hardcoded "Active ✓" would be honest, because neither asked the
854	 * server. This does ask, and reports the answer.
855	 *
856	 * `bump` is incremented after every successful save so the band re-reads the
857	 * live script rather than assuming the save took effect.
858	 */
859	function useRuleStatus(mailboxAddress: string | undefined, bump: number) {
860	  const [status, setStatus] = useState<MailRuleStatus | null>(null);
861	  const [loading, setLoading] = useState(true);
862	
863	  useEffect(() => {
864	    let alive = true;
865	    setLoading(true);
866	    getMailRuleStatus(mailboxAddress)
867	      .then((s) => alive && setStatus(s))
868	      .catch(
869	        () =>
870	          alive &&
871	          // A thrown action (network/auth) must not render as "not active" —
872	          // that would be the same unverified claim in miniature.
873	          setStatus({
874	            supported: false,
875	            autoReplyLive: false,
876	            forwardingLive: false,
877	            error: "Couldn't reach the mail server to check this rule.",
878	          }),
879	      )
880	      .finally(() => alive && setLoading(false));
881	    return () => {
882	      alive = false;
883	    };
884	  }, [mailboxAddress, bump]);
885	
886	  return { status, loading };
887	}
888	
889	/**
890	 * State of one rule on the mail server, compared against what is saved here.
891	 *
892	 * The disagreement case (`savedOn && !live`) is the one worth surfacing loudly:
893	 * it is the only signal a customer gets that the push to the mail server did not
894	 * take, and it is the exact failure the old "Saved." toast used to hide.
895	 */
896	function RuleStatusNote({
897	  status,
898	  loading,
899	  live,
900	  savedOn,
901	  runningText,
902	}: {
903	  status: MailRuleStatus | null;
904	  loading: boolean;
905	  live: boolean;
906	  savedOn: boolean;
907	  runningText: string;
908	}) {
909	  const base = "rounded-xl border px-4 py-3 text-xs";
910	  if (loading || !status) {
911	    return (
912	      <div className={`${base} border-white/[0.08] bg-white/[0.03] text-slate-400`}>
913	        Checking what the mail server is running…
914	      </div>
915	    );
916	  }
917	
918	  if (!status.supported) {
919	    return (
920	      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
921	        This rule is <span className="font-medium">not being applied on the mail server</span>.{" "}
922	        {status.error ?? "Mail rules are unavailable for this mailbox right now."}
923	      </div>
924	    );
925	  }
926	
927	  if (live && savedOn) {
928	    return (
929	      <div className={`${base} border-emerald-400/25 bg-emerald-400/[0.07] text-emerald-200/90`}>
930	        Active on the mail server. {runningText}
931	      </div>
932	    );
933	  }
934	
935	  if (savedOn && !live) {
936	    return (
937	      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
938	        Saved here, but the mail server is <span className="font-medium">not running it</span>. Press
939	        Save changes again — if this keeps coming back, the rule is not active and support should look at
940	        it.
941	      </div>
942	    );
943	  }
944	
945	  if (live && !savedOn) {
946	    return (
947	      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
948	        The mail server is still running a rule for this mailbox even though it is switched off here.
949	        Press Save changes to remove it.
950	      </div>
951	    );
952	  }
953	
954	  return (
955	    <div className={`${base} border-white/[0.08] bg-white/[0.03] text-slate-400`}>
956	      Off — the mail server is not running this rule.
957	    </div>
958	  );
959	}
