1184	function fmtBytes(n: number): string {
1185	  if (!Number.isFinite(n) || n <= 0) return "0 MB";
1186	  const units = ["B", "KB", "MB", "GB", "TB"];
1187	  let v = n;
1188	  let i = 0;
1189	  while (v >= 1024 && i < units.length - 1) {
1190	    v /= 1024;
1191	    i++;
1192	  }
1193	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
1194	}
1195	
1196	function StorageSection({
1197	  initial,
1198	  usedBytes,
1199	  quotaBytes,
1200	}: {
1201	  initial: MailboxSettings;
