1203	  quotaBytes?: number;
1204	}) {
1205	  const quota =
1206	    quotaBytes && quotaBytes > 0
1207	      ? quotaBytes
1208	      : initial.quotaMB
1209	        ? initial.quotaMB * 1024 * 1024
1210	        : 0;
1211	  const used = usedBytes && usedBytes > 0 ? usedBytes : 0;
1212	  const haveUsage = usedBytes !== undefined;
1213	  const pct = quota > 0 ? Math.min(100, Math.round((used / quota) * 100)) : 0;
1214	  const nearFull = pct >= 90;
1215	
1216	  return (
1217	    <div className="space-y-5">
1218	      <SectionHead title="Storage" sub="How much of this mailbox's quota is in use." />
1219	
1220	      <div className="rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5">
1221	        <div className="flex items-baseline justify-between">
1222	          <span className="text-2xl font-semibold text-white">{fmtBytes(used)}</span>
1223	          <span className="text-sm text-slate-400">of {quota > 0 ? fmtBytes(quota) : "—"}</span>
1224	        </div>
1225	
1226	        <div className="mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/10">
1227	          <div
1228	            className={`h-full rounded-full ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
1229	            style={{ width: `${quota > 0 ? pct : 0}%` }}
1230	          />
1231	        </div>
1232	
1233	        <p className="mt-2 text-xs text-slate-500">
1234	          {quota > 0 ? `${pct}% used` : "Quota not set"}
1235	          {!haveUsage && " — live usage is unavailable right now; showing your plan quota."}
1236	          {nearFull && haveUsage && " — you're running low. Clear out large messages or upgrade your plan."}
1237	        </p>
