49	function formatBytes(bytes: number): string {
50	  if (bytes < 1024) return `${bytes} B`;
51	  const kb = bytes / 1024;
52	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
53	  const mb = kb / 1024;
54	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
55	}
