57	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
58	function readFileBase64(file: File): Promise<string> {
59	  return new Promise((resolve, reject) => {
60	    const reader = new FileReader();
61	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
62	    reader.onload = () => {
63	      const result = String(reader.result || "");
64	      const comma = result.indexOf(",");
65	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
66	    };
67	    reader.readAsDataURL(file);
68	  });
69	}
