import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { EmptyState } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { DeployButton } from "@/components/customer/DeployButton";
import { ServersList, type ServerRow } from "@/components/customer/ServersList";
import { effectiveDiskGB } from "@/lib/extra-disk";

export const dynamic = "force-dynamic";

export default async function ServersPage() {
  const user = await requireUser();
  const servers = await db.server.findMany({
    // NxCloud instances are backed by a Server but surfaced as their own product
    // under /dashboard/nxcloud, so they're hidden from the raw VPS list here.
    where: { userId: user.id, nxcloudInstance: { is: null } },
    include: { plan: true, osTemplate: true, project: true },
    orderBy: { createdAt: "desc" },
  });

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  const rows: ServerRow[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
    status: s.status,
    isFree: s.isFree,
    // Effective disk = plan allowance + any separately-purchased extra disk.
    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${effectiveDiskGB(s.plan.diskGB, s.extraDiskGB)} GB`,
    osName: s.osTemplate.name,
    project: s.project ? { name: s.project.name, color: s.project.color } : null,
    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
    created: s.createdAt.toISOString().slice(0, 10),
  }));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PortalHero variant="servers" title="Servers" sub="All virtual machines on your account.">
        <DeployButton href="/dashboard/deploy">Deploy server</DeployButton>
      </PortalHero>

      {servers.length === 0 ? (
        <EmptyState
          title="No servers yet"
          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
          action={
            <DeployButton href="/dashboard/deploy">Deploy your first server</DeployButton>
          }
        />
      ) : (
        <ServersList servers={rows} />
      )}
    </div>
  );
}

