"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { getHostingEmailStatus, setupHostingEmail } from "@/lib/hosting-email";
import type { HostingAccountView } from "@/lib/actions-hosting";
import { Badge } from "@/components/ui/primitives";

type Status = {
  planName?: string;
  primaryDomain?: string;
  includedMailboxes?: number;
  hasSubscription?: boolean;
  subscriptionId?: string;
  verified?: boolean;
  error?: string;
};

/**
 * Bundled hosting email. Reuses the audited /dashboard/email UI for the actual
 * mailbox management + DNS verification — this tab only kicks off the
 * complimentary subscription (setupHostingEmail) and then links across. It never
 * lists or provisions mailboxes itself.
 */
export function EmailTab({ account }: { account: HostingAccountView }) {
  const [status, setStatus] = useState<Status | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  function refresh() {
    getHostingEmailStatus(account.id)
      .then((s) => setStatus(s))
      .catch(() => setStatus({ error: "Couldn’t load email status." }));
  }

  useEffect(() => {
    refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [account.id]);

  async function setup() {
    setBusy(true);
    setErr(null);
    const r = await setupHostingEmail(account.id);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    refresh();
  }

  if (!status) {
    return <div className="card py-12 text-center text-sm text-slate-400">Loading email…</div>;
  }
  if (status.error) {
    return <div className="card py-12 text-center text-sm text-red-300">{status.error}</div>;
  }

  const count = status.includedMailboxes ?? 0;
  const mailboxWord = count === 1 ? "mailbox" : "mailboxes";

  return (
    <div className="space-y-6">
      <div className="card">
        <div className="mb-4 flex items-center justify-between gap-2">
          <h2 className="font-semibold">Email</h2>
          {status.hasSubscription && (
            <Badge tone={status.verified ? "green" : "amber"}>
              {status.verified ? "Active" : "Verify DNS"}
            </Badge>
          )}
        </div>

        <p className="text-sm text-slate-300">
          Your <span className="font-medium text-white">{status.planName}</span> plan includes{" "}
          <span className="font-medium text-white">{count} {mailboxWord}</span> on{" "}
          <span className="font-mono text-slate-200">{status.primaryDomain}</span> — professional
          you@yourdomain email at no extra cost.
        </p>

        {!status.hasSubscription ? (
          <>
            <p className="mt-3 text-sm text-slate-400">
              Set up email to claim your included {mailboxWord}. You’ll then add addresses and
              publish the DNS records that route mail to Nxeon.
            </p>
            {err && <div className="card mt-4 border-red-500/30 text-sm text-red-300">{err}</div>}
            <button type="button" className="btn-primary mt-4" disabled={busy} onClick={setup}>
              {busy ? "Setting up…" : "Set up my email"}
            </button>
          </>
        ) : (
          <>
            <p className="mt-3 text-sm text-slate-400">
              {status.verified
                ? "Your domain is verified. Add and manage mailboxes from the email dashboard."
                : "Almost there — add your mailboxes and publish the DNS records shown on the email dashboard to start receiving mail."}
            </p>
            <Link href="/dashboard/email" className="btn-primary mt-4 inline-block">
              Manage mailboxes →
            </Link>
          </>
        )}
      </div>
    </div>
  );
}
